-- FIT90 legacy subscriptions import. Run this only after 06_import_members_fit90.sql.
-- membership records are matched to members by normalized phone. System-transfer and InBody rows keep a NULL package id.
SET NAMES utf8mb4;
START TRANSACTION;
DROP TEMPORARY TABLE IF EXISTS `tmp_fit90_subscription_import`;
CREATE TEMPORARY TABLE `tmp_fit90_subscription_import` (
  `external_id` VARCHAR(50) NOT NULL,
  `phone` VARCHAR(30) NULL,
  `customer_name` VARCHAR(200) NULL,
  `package_name` VARCHAR(150) NULL,
  `package_lookup_name` VARCHAR(150) NULL,
  `registration_date` VARCHAR(10) NULL,
  `start_date` VARCHAR(10) NULL,
  `end_date` VARCHAR(10) NULL,
  `gender` VARCHAR(10) NULL,
  `status` VARCHAR(20) NOT NULL,
  `subscription_value` DECIMAL(10,2) NOT NULL,
  `discount_value` DECIMAL(10,2) NOT NULL,
  `paid_amount` DECIMAL(10,2) NOT NULL,
  `remaining_amount` DECIMAL(10,2) NOT NULL,
  `receipt_number` VARCHAR(30) NULL,
  `sales_name` VARCHAR(200) NULL,
  `coach_name` VARCHAR(200) NULL,
  `legacy_notes` TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;










