  `subscription_number`, `registration_date`, `branch_id`, `member_id`, `customer_name`,
  `subscription_type_id`, `subscription_type`, `subscription_start_date`, `subscription_end_date`,
  `subscription_value`, `discount_enabled`, `discount_value`, `paid_amount`, `remaining_amount`,
  `gender`, `receipt_number`, `status`, `is_special`, `is_linked_to_sessions`, `sessions_count`,
  `sessions_used`, `is_time_based`, `created_at`, `updated_at`
)
SELECT
  CONCAT('IMP-S-', t.`external_id`),
  COALESCE(t.`registration_date`, t.`start_date`),
  1,
  m.`id`,
  t.`customer_name`,
  st.`id`,
  t.`package_name`,
  COALESCE(t.`start_date`, t.`registration_date`),
  COALESCE(t.`end_date`, t.`start_date`, t.`registration_date`),
  t.`subscription_value`,
  CASE WHEN t.`discount_value` <> 0 THEN 1 ELSE 0 END,
  t.`discount_value`,
  t.`paid_amount`,
  t.`remaining_amount`,
  t.`gender`,
  t.`receipt_number`,
  t.`status`,
  COALESCE(st.`is_special_offer`, 0),
  COALESCE(st.`is_linked_to_sessions`, 0),
  st.`sessions_count`,
  0,
  0,
  NOW(), NOW()
FROM `tmp_fit90_subscription_import` t
LEFT JOIN `club_members` m
  ON CONVERT(m.`phone` USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(t.`phone` USING utf8mb4) COLLATE utf8mb4_unicode_ci
  AND m.`branch_id` = 1 AND m.`is_deleted` = 0
LEFT JOIN `club_subscription_types` st
  ON st.`branch_id` = 1
  AND t.`package_lookup_name` IS NOT NULL
  AND LOWER(TRIM(CONVERT(st.`name` USING utf8mb4))) COLLATE utf8mb4_unicode_ci = LOWER(TRIM(CONVERT(t.`package_lookup_name` USING utf8mb4))) COLLATE utf8mb4_unicode_ci
ON DUPLICATE KEY UPDATE
  `member_id` = VALUES(`member_id`), `customer_name` = VALUES(`customer_name`),
  `subscription_type_id` = VALUES(`subscription_type_id`), `subscription_type` = VALUES(`subscription_type`),
  `subscription_start_date` = VALUES(`subscription_start_date`), `subscription_end_date` = VALUES(`subscription_end_date`),
  `subscription_value` = VALUES(`subscription_value`), `discount_enabled` = VALUES(`discount_enabled`),
  `discount_value` = VALUES(`discount_value`), `paid_amount` = VALUES(`paid_amount`),
  `remaining_amount` = VALUES(`remaining_amount`), `gender` = VALUES(`gender`),
  `receipt_number` = VALUES(`receipt_number`), `status` = VALUES(`status`),
  `is_special` = VALUES(`is_special`), `is_linked_to_sessions` = VALUES(`is_linked_to_sessions`),
  `sessions_count` = VALUES(`sessions_count`), `updated_at` = NOW();

COMMIT;
SELECT COUNT(*) AS imported_subscriptions FROM `club_subscriptions` WHERE `branch_id` = 1 AND `subscription_number` LIKE 'IMP-S-%';
SELECT COUNT(*) AS subscriptions_without_member FROM `club_subscriptions` WHERE `branch_id` = 1 AND `subscription_number` LIKE 'IMP-S-%' AND `member_id` IS NULL;
SELECT COUNT(*) AS subscriptions_without_type FROM `club_subscriptions` WHERE `branch_id` = 1 AND `subscription_number` LIKE 'IMP-S-%' AND `subscription_type_id` IS NULL;
